import copy, json
from work import evaluate

def verify(req, pol, expected):
    req_before = copy.deepcopy(req)
    pol_before = copy.deepcopy(pol)
    actual = evaluate(req, pol)
    assert actual == expected, (actual, expected)
    assert req == req_before and pol == pol_before
    assert set(actual) == {'ok','records','errors'}
    for record in actual['records']:
        assert set(record) == {'id','amount'}
    for error in actual['errors']:
        assert set(error) == {'row','cause'}

p = {'base_unit':'m','units':{'m':1,'cm':0.01},'unique':True}
verify({'rows':[{'id':'a','amount':2,'unit':'cm'},{'id':'b','amount':3}]}, p, {'ok':True,'records':[{'id':'a','amount':0.02},{'id':'b','amount':3}],'errors':[]})
